import React from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

export default function Navbar({ showAuthButtons = false, onAboutClick, onContactClick, onInfoClick }) {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const handleLogout = () => { logout(); navigate('/'); };
  const infoItems = ['Features', 'Catalogue', 'Academics', 'Departments'];

  return (
    <nav style={{
      background: '#ffffff',
      backdropFilter: 'blur(20px)',
      borderBottom: '1px solid #dbeafe',
      position: 'fixed', top: 0, left: 0, right: 0, zIndex: 50,
      boxShadow: '0 4px 24px rgba(15,23,42,0.08)'
    }}>
      <div className="page-shell" style={{ paddingTop: '1rem', paddingBottom: '1rem', display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '1rem', flexWrap: 'wrap' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
          <div style={{
            width: 42, height: 42, borderRadius: '0.75rem',
            background: '#eff6ff', border: '1px solid #bfdbfe',
            display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.5rem'
          }}>🏛️</div>
          <h1 className="title-font" style={{ fontSize: '1.5rem' }}>VEMU LIBRARY SYSTEM</h1>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'flex-end', gap: '1rem', flexWrap: 'wrap', marginLeft: 'auto' }}>
          {user ? (
            <>
              <div style={{
                display: 'flex', alignItems: 'center', gap: '0.5rem',
                background: 'rgba(255,255,255,0.15)', borderRadius: '2rem',
                padding: '0.4rem 1rem', border: '1px solid rgba(255,255,255,0.25)',
                fontSize: '0.8rem'
              }}>
                👤 <span>{user.name}</span>
                <span style={{ color: '#FFD966', fontWeight: 700, fontSize: '0.7rem' }}>{user.role.toUpperCase()}</span>
              </div>
              <button onClick={handleLogout} className="btn-primary" style={{ padding: '0.5rem 1.25rem', fontSize: '0.8rem' }}>
                LOGOUT
              </button>
            </>
          ) : showAuthButtons ? (
            <>
              {infoItems.map((item) => (
                <span
                  key={item}
                  onClick={() => onInfoClick && onInfoClick(item)}
                  style={{ fontSize: '0.88rem', fontWeight: 700, cursor: 'pointer', opacity: 0.9, color: '#1e3a8a' }}
                >
                  {item}
                </span>
              ))}
              {onAboutClick ? (
                <span
                  onClick={onAboutClick}
                  style={{ fontSize: '0.88rem', fontWeight: 700, cursor: 'pointer', opacity: 0.9, color: '#1e3a8a' }}
                >
                  About
                </span>
              ) : null}
              {onContactClick ? (
                <span
                  onClick={onContactClick}
                  style={{ fontSize: '0.88rem', fontWeight: 700, cursor: 'pointer', opacity: 0.9, color: '#1e3a8a' }}
                >
                  Contact
                </span>
              ) : null}
              <button onClick={() => navigate('/login')} className="btn-ghost" style={{ padding: '0.5rem 1.5rem' }}>LOGIN</button>
              <button onClick={() => navigate('/register')} className="btn-primary" style={{ padding: '0.5rem 1.5rem' }}>REGISTER</button>
            </>
          ) : null}
        </div>
      </div>
    </nav>
  );
}
